package com.magraoxx.eichattv;
import android.Manifest;import android.app.Activity;import android.content.pm.PackageManager;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.os.Bundle;import android.speech.tts.TextToSpeech;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity{
 private static final int REQ_MIC=1001;private TextView status,caption,micText;private TextToSpeech tts;private CommandEngine engine;private OpenAiClient ai;private ChatGptAuth auth;private AiVoiceRecorder recorder;private boolean pending;
 public void onCreate(Bundle b){super.onCreate(b);engine=new CommandEngine(this);ai=new OpenAiClient(this);auth=new ChatGptAuth(this);recorder=new AiVoiceRecorder(this);buildUi();tts=new TextToSpeech(this,x->{if(x==0){tts.setLanguage(new Locale("pt","BR"));tts.setSpeechRate(1.02f);}});if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},REQ_MIC);if(getIntent()!=null&&getIntent().getBooleanExtra("start_listening",false))startListening();}
 private TextView text(String s,float z){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(z);return v;}private GradientDrawable bg(int c,float r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(r);return g;}private Button button(String s,View.OnClickListener l){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(17);b.setTextColor(Color.BLACK);b.setFocusable(true);b.setOnClickListener(l);return b;}
 private void buildUi(){FrameLayout root=new FrameLayout(this);root.setBackgroundColor(Color.rgb(12,14,18));LinearLayout center=new LinearLayout(this);center.setOrientation(LinearLayout.VERTICAL);center.setGravity(Gravity.CENTER);center.setPadding(70,50,70,50);root.addView(center,new FrameLayout.LayoutParams(-1,-1));TextView logo=text("Ei Chat",42);logo.setGravity(17);logo.setTypeface(null,1);center.addView(logo,new LinearLayout.LayoutParams(-1,-2));caption=text("Assistente com IA",20);caption.setGravity(17);caption.setTextColor(Color.LTGRAY);center.addView(caption);LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setPadding(38,28,38,28);card.setBackground(bg(Color.rgb(30,33,40),30));LinearLayout.LayoutParams cp=new LinearLayout.LayoutParams(-1,-2);cp.setMargins(0,45,0,20);center.addView(card,cp);status=text("Pressione OUVIR e fale normalmente",26);status.setGravity(17);card.addView(status);micText=text("● IA pronta",17);micText.setGravity(17);micText.setPadding(0,18,0,8);card.addView(micText);Button listen=button("🎤  OUVIR COM IA",v->startListening());LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(420,70);bp.gravity=1;bp.setMargins(0,22,0,8);center.addView(listen,bp);Button diag=button("Diagnóstico",v->{caption.setText("Ei Chat • diagnóstico");status.setText(TvMicrophone.report(this)+"\nChatGPT: "+auth.accountLabel());});LinearLayout.LayoutParams dp=new LinearLayout.LayoutParams(420,60);dp.gravity=1;center.addView(diag,dp);setContentView(root);}
 private void startListening(){if(checkSelfPermission(Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){pending=true;requestPermissions(new String[]{Manifest.permission.RECORD_AUDIO},REQ_MIC);return;}caption.setText("Ei Chat • ouvindo");status.setText("Pode falar…");micText.setText(TvMicrophone.findBuiltIn(this)!=null?"● capturando microfone interno para IA":"● capturando áudio para IA");recorder.record(new AiVoiceRecorder.Callback(){public void onRecorded(java.io.File wav,String route){runOnUiThread(()->{caption.setText("Ei Chat • transcrevendo com IA");status.setText("Entendendo sua voz…");micText.setText("● "+route);});ai.transcribe(wav,new OpenAiClient.Callback(){public void onSuccess(String q){runOnUiThread(()->handle(q));}public void onError(String e){runOnUiThread(()->{caption.setText("Ei Chat");status.setText(e);micText.setText("● verifique conexão/login");});}});}public void onError(String e){runOnUiThread(()->status.setText("Microfone: "+e));}});}
 private void handle(String q){caption.setText("Você disse");status.setText("“"+q+"”");CommandEngine.Result r=engine.execute(q);if(r.handled){caption.setText("Ei Chat");status.setText(r.message);if(!r.success)speak(r.message);return;}caption.setText("Ei Chat • pensando com IA");status.setText("Pensando…");ai.ask(q,new OpenAiClient.Callback(){public void onSuccess(String x){runOnUiThread(()->{caption.setText("Ei Chat");status.setText(x);speak(x);});}public void onError(String x){runOnUiThread(()->{caption.setText("Ei Chat");status.setText(x);});}});}
 private void speak(String x){if(tts!=null&&x!=null&&!x.trim().isEmpty())tts.speak(x,TextToSpeech.QUEUE_FLUSH,null,"ei_chat");}
 public void onRequestPermissionsResult(int c,String[] p,int[] g){super.onRequestPermissionsResult(c,p,g);if(c==REQ_MIC&&g.length>0&&g[0]==PackageManager.PERMISSION_GRANTED&&pending){pending=false;startListening();}}protected void onDestroy(){recorder.stop();if(tts!=null)tts.shutdown();super.onDestroy();}
}
